<?php namespace Workspace; ?>
<p>Личный центр напоминаний. Источники проверяются при каждом открытии; завершённые и недоступные объекты не отображаются. Даты — UTC.</p>
<?php if(!mfaFresh()): ?><p><a href="<?= h(url('security')) ?>">Подтвердить второй фактор</a> для договоров и инцидентов.</p><?php endif ?>
<?php if($user['role']==='owner'): ?><p><a href="<?= h(url('digest',['project'=>$project??''])) ?>">Сводка владельцу</a></p><?php endif ?>
<section class="panel inset"><form method="get" class="inline"><input type="hidden" name="p" value="notifications"><label>Проект<select name="project"><?php selectOptions([''=>'Все доступные']+$projects,$project??'') ?></select></label><label>Тип<select name="kind"><?php selectOptions([''=>'Все']+$labels,$filter) ?></select></label><label>Показать<select name="unread"><?php selectOptions(['0'=>'Все','1'=>'Непрочитанные'],$unread?'1':'0') ?></select></label><button>Показать</button></form></section>
<section class="panel inset"><h2>Личные подписки</h2><?php if($project!==null&&$options): ?><form method="post" class="inline"><?php formFields('reminder.subscribe') ?><input type="hidden" name="project_id" value="<?= h($project) ?>"><label>Тип<select name="kind"><?php selectOptions($options,'') ?></select></label><label>Дней до срока<input type="number" name="lead" min="0" max="90" value="7" required></label><label>Охват<select name="assigned"><?php selectOptions(['0'=>'Все доступные','1'=>'Только назначенные мне (задачи, договоры, инциденты)'],'0') ?></select></label><button class="primary" name="enable" value="1">Сохранить подписку</button></form><?php else: ?><p>Выберите проект для создания или изменения подписки.</p><?php endif ?>
<?php foreach($subscriptions as $sub): ?><div class="splitrow"><span><?= h($sub['project_title'].' · '.$labels[$sub['kind']].' · '.$sub['lead_days'].' дн.'.((int)$sub['assigned_only']?' · мои':'') ) ?></span><form method="post"><?php formFields('reminder.subscribe') ?><input type="hidden" name="project_id" value="<?= h($sub['project_id']) ?>"><input type="hidden" name="kind" value="<?= h($sub['kind']) ?>"><input type="hidden" name="lead" value="0"><input type="hidden" name="assigned" value="0"><button class="secondary" name="enable" value="0">Отписаться</button></form></div><?php endforeach ?><?php if(!$subscriptions): ?><p class="empty">Нет доступных подписок.</p><?php endif ?></section>
<?php foreach($errors as $k=>$message): ?><p class="notice"><?= h($labels[$k].': '.$message) ?></p><?php endforeach ?>
<?php foreach($groups as $k=>$rows): if(!$rows&&!isset($errors[$k]))continue; ?><section class="panel"><div class="panelhead"><h2><?= h($labels[$k]) ?></h2><span class="count"><?= count($rows) ?></span></div><?php foreach($rows as $r): $epoch=$k==='incidents';$late=$epoch?(int)$r['deadline']<=$now:$r['deadline']<gmdate('Y-m-d',$now); ?><div class="splitrow"><div><a href="<?= h(discoveryHref($r,$k)) ?>"><?= h($r['title']) ?></a><p class="muted"><?= h($r['project_title'].' · '.($epoch?gmdate('Y-m-d H:i:s',(int)$r['deadline']).' UTC':$r['deadline']).($late?' · ПРОСРОЧЕНО':'').($r['read_at']?' · прочитано':' · новое')) ?></p></div><form method="post"><?php formFields('reminder.mark') ?><input type="hidden" name="subscription" value="<?= h($r['subscription_id']) ?>"><input type="hidden" name="object" value="<?= h($r['id']) ?>"><input type="hidden" name="deadline" value="<?= h($r['deadline_key']) ?>"><button class="secondary" name="read" value="<?= $r['read_at']?'0':'1' ?>"><?= $r['read_at']?'Не прочитано':'Прочитано' ?></button></form></div><?php endforeach ?><?php if($more[$k]??false): ?><p><a href="<?= h(url('notifications',['project'=>$project??'','kind'=>$k,'n'=>$filter===$k?$page+1:1,'unread'=>$unread?'1':'0'])) ?>"><?= $filter===$k?'Следующая страница':'Все напоминания типа' ?></a></p><?php endif ?><?php if($filter===$k&&$page>1): ?><p><a href="<?= h(url('notifications',['project'=>$project??'','kind'=>$k,'n'=>$page-1,'unread'=>$unread?'1':'0'])) ?>">Назад</a></p><?php endif ?></section><?php endforeach ?>
<?php if(!array_filter($groups)&&!$errors): ?><p class="empty">Нет напоминаний в выбранной выборке.</p><?php endif ?>

<?php if(isset($freelanceReminders)): ?><section class="panel inset"><h2>Просроченные клиентские счета</h2><?php if(!$freelanceReminders): ?><p>Просроченных связанных счетов нет.</p><?php endif ?><?php foreach(array_slice($freelanceReminders,0,50) as $r): ?><p><a href="<?= h(url('clients',['id'=>$r['order_id']])) ?>"><?= h($r['title']) ?></a> · <a href="<?= h(url('invoices',['project'=>$r['project_id'],'id'=>$r['invoice_id']])) ?>">Счёт #<?= h($r['invoice_id']) ?></a> · <?= h(money((int)$r['outstanding']).' '.$r['currency']) ?> · <?= h(displayDate($r['due_on'])) ?></p><?php endforeach ?><?php if(count($freelanceReminders)>50): ?><p>Показаны первые 50 просроченных счетов; уточните проект.</p><?php endif ?></section><?php endif ?>
